INSERT INTO comments (id, post_id, user_id, parent_id, content, created_at, updated_at) VALUES
  ('00000006-0000-0000-0000-000000000001', '00000005-0000-0000-0000-000000000001', '00000001-0000-0000-0000-000000000002', null,                                   '저도 오늘부터 6시 기상 도전해볼게요!',   now(), now()),
