  ('00000006-0000-0000-0000-000000000003', '00000005-0000-0000-0000-000000000001', '00000001-0000-0000-0000-000000000001', '00000006-0000-0000-0000-000000000001', '같이 해봐요! 파이팅!',                   now(), now()),
  ('00000006-0000-0000-0000-000000000004', '00000005-0000-0000-0000-000000000002', '00000001-0000-0000-0000-000000000001', null,                                   '토익 어떻게 공부하세요? 팁 부탁드려요!', now(), now()),
