  ('00000006-0000-0000-0000-000000000008', '00000005-0000-0000-0000-000000000005', '00000001-0000-0000-0000-000000000002', null,                                   '365일 도전 꼭 성공하세요!',               now(), now()),
  ('00000006-0000-0000-0000-000000000009', '00000005-0000-0000-0000-000000000005', '00000001-0000-0000-0000-000000000006', null,                                   '루틴 공유해주세요~',                     now(), now()),
  ('00000006-0000-0000-0000-000000000010', '00000005-0000-0000-0000-000000000005', '00000001-0000-0000-0000-000000000007', null,                                   '저도 아침 루틴 시작했어요!',              now(), now()),
  ('00000006-0000-0000-0000-000000000011', '00000005-0000-0000-0000-000000000006', '00000001-0000-0000-0000-000000000001', null,                                   '어떤 책 읽으셨어요?',                    now(), now()),
