INSERT INTO team_messages (id, team_room_id, sender_id, content, created_at) VALUES
  ('00000008-0000-0000-0000-000000000001', '00000007-0000-0000-0000-000000000001', '00000001-0000-0000-0000-000000000001', '안녕하세요! 갓생 클럽 개설했어요',          now() - interval '3 hour'),
  ('00000008-0000-0000-0000-000000000002', '00000007-0000-0000-0000-000000000001', '00000001-0000-0000-0000-000000000002', '오! 가입했습니다. 같이 갓생 살아봐요!',     now() - interval '2 hour'),
  ('00000008-0000-0000-0000-000000000003', '00000007-0000-0000-0000-000000000001', '00000001-0000-0000-0000-000000000003', '저도 합류! 오늘 공부 인증 올릴게요',        now() - interval '1 hour'),
  ('00000008-0000-0000-0000-000000000004', '00000007-0000-0000-0000-000000000001', '00000001-0000-0000-0000-000000000005', '아침 루틴 완료! D+42 달성했어요',           now() - interval '30 minute'),
  ('00000008-0000-0000-0000-000000000005', '00000007-0000-0000-0000-000000000002', '00000001-0000-0000-0000-000000000008', '코딩 스터디 시작합니다. 오늘 주제는 JPA!', now() - interval '2 hour'),
  ('00000008-0000-0000-0000-000000000006', '00000007-0000-0000-0000-000000000002', '00000001-0000-0000-0000-000000000003', 'N+1 문제 해결법 공유해드릴게요',            now() - interval '1 hour'),
  ('00000008-0000-0000-0000-000000000007', '00000007-0000-0000-0000-000000000002', '00000001-0000-0000-0000-000000000007', '저는 QueryDSL도 같이 공부하고 싶어요!',     now() - interval '20 minute')
